cd "/d/Temp/claude/3db4783c4b24ca36/fd501d7a-3e55-45ba-9bd0-80a39b24c9ec/scratchpad/d407/dl" && cat > /d/Temp/claude/3db4783c4b24ca36/fd501d7a-3e55-45ba-9bd0-80a39b24c9ec/scratchpad/d407/lbl.py <<'EOF'
import json,sys,re
d=json.load(open(sys.argv[1],encoding='utf-8'))
r=d['results'][0]
print('effective_time',r.get('effective_time'),'version',r.get('version'), r.get('openfda',{}).get('brand_name'), r.get('openfda',{}).get('manufacturer_name'))
keys=sys.argv[2].split(',')
pats=sys.argv[3].split('|') if len(sys.argv)>3 else []
for k in keys:
    if k in r:
        t=' '.join(r[k])
        if pats:
            for p in pats:
                for m in re.finditer(p,t,flags=re.I):
                    s=max(0,m.start()-300); e=min(len(t),m.end()+400)
                    print(f'[{k}] ...{t[s:e]}...\n')
        else:
            print(f'[{k}]',t[:3000],'\n')
EOF
